ee:message.ee:set-payload:
%dw 2.0 output application/java
var raw = (vars.gxContent as String) replace "\n" with "" replace " " with ""
var xml = fromBase64(raw) as String {encoding:"UTF-8"}
// P = "$" — prevents Mule startup resolver from scanning Zuul property refs.
// At DataWeave runtime: P concatenated with "{zuul::sap.host}" builds the
// property placeholder that is written verbatim into the target global.xml.
var P = "$"
// Extended Properties (Advanced tab > Edit Inline) — image 2:
//   jco.client.mshost, jco.client.msserv, jco.client.group, jco.client.saprouter
// Message Server (General tab > HOST > Edit Inline) — image 3:
//   host, systemId, port, group + SAP router /H/52.4.121.113
var newKids =
    ">\n            <sap:extended-properties>\n" ++
    "                <sap:extended-property key=\"jco.client.mshost\" value=\"" ++ P ++ "{zuul::sap.host}\"/>\n" ++
    "                <sap:extended-property key=\"jco.client.msserv\" value=\"" ++ P ++ "{zuul::sap.port}\"/>\n" ++
    "                <sap:extended-property key=\"jco.client.group\" value=\"" ++ P ++ "{zuul::sap.logon.group}\"/>\n" ++
    "                <sap:extended-property key=\"jco.client.saprouter\" value=\"/H/52.4.121.113\"/>\n" ++
    "            </sap:extended-properties>\n" ++
    "            <sap:message-server" ++
    " host=\"" ++ P ++ "{zuul::sap.host}\"" ++
    " systemId=\"" ++ P ++ "{zuul::sap.r3Name}\"" ++
    " port=\"" ++ P ++ "{zuul::sap.port}\"" ++
    " group=\"" ++ P ++ "{zuul::sap.logon.group}\"/>\n" ++
    "        </sap:simple-connection-provider-connection>"
// Remove applicationServerHost — App Server and Message Server must NOT be mixed
var updated = xml replace /<sap:simple-connection-provider-connection([^>]*)\/>/
    with (g) -> do {
        var cleanAttrs = (g[1] default "") replace /\s+applicationServerHost="[^"]*"/ with ""
        ---
        "<sap:simple-connection-provider-connection" ++ cleanAttrs ++ newKids
    }
--- {encoded: toBase64(updated as Binary {encoding:"UTF-8"})}
